-- ============================================================
-- BLOCK 1: Schema
-- ============================================================

CREATE TABLE IF NOT EXISTS public.email_logs (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID REFERENCES auth.users(id) ON DELETE SET NULL,
    recipient_email TEXT NOT NULL,
    email_type TEXT NOT NULL,               -- e.g. 'payment_failed', 'trial_expiring'
    notification_category TEXT,             -- maps to notification_preferences.category
    is_critical BOOLEAN NOT NULL DEFAULT false,
    status TEXT NOT NULL DEFAULT 'pending'
        CHECK (status IN ('pending', 'sent', 'bounced', 'failed', 'skipped')),
    sendgrid_message_id TEXT,
    unsubscribe_token TEXT UNIQUE DEFAULT encode(gen_random_bytes(32), 'hex'),
    sent_at TIMESTAMPTZ,
    failed_at TIMESTAMPTZ,
    error_message TEXT,
    metadata JSONB NOT NULL DEFAULT '{}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

COMMENT ON TABLE public.email_logs IS 'NOTIF-V2-009: Outbound email delivery log with tracking and unsubscribe token';
COMMENT ON COLUMN public.email_logs.unsubscribe_token IS 'One-click unsubscribe token included in every email footer';
COMMENT ON COLUMN public.email_logs.notification_category IS 'Maps to notification_preferences.category for opt-out routing';
COMMENT ON COLUMN public.email_logs.is_critical IS 'Critical emails bypass user opt-out preferences';

-- ============================================================
-- Indexes
-- ============================================================
CREATE INDEX IF NOT EXISTS idx_email_logs_user_id        ON public.email_logs(user_id);
CREATE INDEX IF NOT EXISTS idx_email_logs_email_type     ON public.email_logs(email_type);
CREATE INDEX IF NOT EXISTS idx_email_logs_status         ON public.email_logs(status);
CREATE INDEX IF NOT EXISTS idx_email_logs_unsubscribe    ON public.email_logs(unsubscribe_token);
CREATE INDEX IF NOT EXISTS idx_email_logs_created_at     ON public.email_logs(created_at DESC);

-- ============================================================
-- BLOCK 2: Security (RLS)
-- ============================================================
ALTER TABLE public.email_logs ENABLE ROW LEVEL SECURITY;

-- Users can read their own email logs (for receipt history)
DROP POLICY IF EXISTS "email_logs_select_own" ON public.email_logs;
CREATE POLICY "email_logs_select_own" ON public.email_logs
    FOR SELECT TO authenticated
    USING (user_id = auth.uid());

-- Only service role can insert/update (edge functions use service role key)
DROP POLICY IF EXISTS "email_logs_service_role" ON public.email_logs;
CREATE POLICY "email_logs_service_role" ON public.email_logs
    FOR ALL TO service_role
    USING (true)
    WITH CHECK (true);

