NOTIF-V2-009: Generate secure random unsubscribe token
function generateUnsubscribeToken(): string {
  const buffer = new Uint8Array(32);
  crypto.getRandomValues(buffer);
  return Array.from(buffer).map(b => b.toString(16).padStart(2, '0')).join('');
}

// NOTIF-V2-009: Log email delivery to email_logs table
async function logEmailDelivery(params: {
  userId?: string;
  recipientEmail: string;
  emailType: string;
  notificationCategory?: string;
  isCritical: boolean;
  status: 'sent' | 'failed' | 'skipped';
  sendgridMessageId?: string;
  errorMessage?: string;
  unsubscribeToken: string;
  metadata?: Record<string, any>;
}): Promise<void> {
  if (!SUPABASE_URL || !SUPABASE_SERVICE_ROLE_KEY) return;
  try {
    const { createClient } = await import('https://esm.sh/@supabase/supabase-js@2.39.0');
    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
    const { error } = await supabase.from('email_logs').insert({
      user_id: params.userId || null,
      recipient_email: params.recipientEmail,
      email_type: params.emailType,
      notification_category: params.notificationCategory || null,
      is_critical: params.isCritical,
      status: params.status,
      sendgrid_message_id: params.sendgridMessageId || null,
      unsubscribe_token: params.unsubscribeToken,
      sent_at: params.status === 'sent' ? new Date().toISOString() : null,
      failed_at: params.status === 'failed' ? new Date().toISOString() : null,
      error_message: params.errorMessage || null,
      metadata: params.metadata || {},
    });
    if (error) console.error('[send-email] Logging failed:', error.message);
  } catch (err) {
    console.error('[send-email] Logging exception:', err);
  }
}

// NOTIF-V2-009: Build mobile-responsive email footer with unsubscribe link
function buildEmailFooter(unsubscribeToken: string, isCritical: boolean): string {
  const unsubscribeUrl = `${UNSUBSCRIBE_BASE_URL}?token=${unsubscribeToken}`;
  const optOutSection = isCritical
    ? '<p style="margin:0;font-size:12px;color:#9CA3AF;">This is a critical account notification and cannot be opted out.</p>'
    : `<p style="margin:0;font-size:12px;color:#9CA3AF;">Don't want these emails? <a href="${unsubscribeUrl}" style="color:#6B7280;">Unsubscribe</a></p>`;
  return `
    <div style="margin-top:32px;padding-top:24px;border-top:1px solid #E5E7EB;text-align:center;">
      <p style="margin:0 0 8px;font-size:13px;color:#6B7280;">P2P Kids Marketplace &nbsp;|&nbsp; <a href="https://p2pkidsmarketplace.com" style="color:#6B7280;text-decoration:none;">Website</a></p>
      ${optOutSection}
    </div>`;
}

// NOTIF-V2-009: Build mobile-responsive email wrapper
function buildEmailHtml(title: string, bodyHtml: string, unsubscribeToken: string, isCritical: boolean): string {
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${title}</title>
