// NOTIF-V2-009: Supabase client for email delivery logging
const SUPABASE_URL = Deno.env.get('SUPABASE_URL') ?? '';
const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '';
const UNSUBSCRIBE_BASE_URL = `${SUPABASE_URL}/functions/v1/email-unsubscribe`;

// =============================================================================
// NOTIF-V2-009: New email handlers (payment_failed, trial_expiring,
//               subscription_cancelled, account_security_alert)
// =============================================================================

async function processPaymentFailedEmail(
  to: string,
  unsubscribeToken: string,
  data?: Record<string, any>
): Promise<{ success: boolean; messageId?: string; error?: string }> {
  const amount = data?.amount ? `$${Number(data.amount).toFixed(2)}` : '';
  const reason = data?.reason || 'Your card was declined';
  const retryLink = data?.retry_link || 'https://p2pkidsmarketplace.com/subscription/payment';

  const bodyHtml = `
    <h2 style="margin:0 0 16px;color:#111827;font-size:22px;">⚠️ Payment Failed</h2>
    <p style="margin:0 0 12px;color:#374151;font-size:15px;line-height:1.6;">
      We weren't able to process your Kids Club+ subscription payment${amount ? ` of <strong>${amount}</strong>` : ''}.
    </p>
    <div style="background:#FEF2F2;border-left:4px solid #EF4444;padding:16px;border-radius:4px;margin:0 0 24px;">
      <strong style="color:#991B1B;">Reason:</strong>
      <span style="color:#7F1D1D;"> ${reason}</span>
    </div>
    <p style="margin:0 0 24px;color:#374151;font-size:15px;line-height:1.6;">
      Please update your payment method to keep your Kids Club+ benefits active, including Swap Points access.
    </p>
    <div style="text-align:center;">
      <a href="${retryLink}"
         style="display:inline-block;background:#3B82F6;color:#ffffff;padding:14px 28px;border-radius:8px;text-decoration:none;font-weight:600;font-size:15px;">
        Update Payment Method
      </a>
    </div>`;

  if (!SENDGRID_API_KEY) return { success: false, error: 'SendGrid API key not configured' };

  const html = buildEmailHtml('Payment Failed – Kids Club+', bodyHtml, unsubscribeToken, true);
  try {
    const response = await fetch('https://api.sendgrid.com/v3/mail/send', {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${SENDGRID_API_KEY}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({
        personalizations: [{ to: [{ email: to }] }],
        from: { email: SENDGRID_FROM_EMAIL },
        reply_to: { email: SENDGRID_REPLY_TO_EMAIL },
        subject: 'Payment Failed – Action Required for Kids Club+',
        content: [{ type: 'text/html', value: html }],
      }),
    });
    if (!response.ok) {
      const errText = await response.text();
      return { success: false, error: `SendGrid ${response.status}: ${errText}` };
    }
    return { success: true, messageId: response.headers.get('x-message-id') || undefined };
  } catch (err) {
    return { success: false, error: err instanceof Error ? err.message : 'Unknown error' };
  }
}

async function processTrialExpiringEmail(
  to: string,
  unsubscribeToken: string,
  data?: Record<string, any>
): Promise<{ success: boolean; messageId?: string; error?: string }> {
  const daysRemaining = data?.days_remaining ?? 7;
  const trialEndsAt = data?.trial_ends_at || 'soon';
  const subscribeLink = data?.subscribe_link || 'https://p2pkidsmarketplace.com/subscription';

  const urgency = daysRemaining <= 1 ? '#EF4444' : daysRemaining <= 3 ? '#F59E0B' : '#3B82F6';
  const emoji = daysRemaining <= 1 ? '🚨' : daysRemaining <= 3 ? '⏰' : '🎉';

  const bodyHtml = `
    <h2 style="margin:0 0 16px;color:#111827;font-size:22px;">${emoji} ${daysRemaining} Day${daysRemaining !== 1 ? 's' : ''} Left in Your Trial</h2>
    <p style="margin:0 0 12px;color:#374151;font-size:15px;line-height:1.6;">
      Your Kids Club+ free trial ends on <strong>${trialEndsAt}</strong>.
    </p>
    <p style="margin:0 0 24px;color:#374151;font-size:15px;line-height:1.6;">
      Subscribe now to keep your Swap Points active and continue enjoying:
    </p>
    <ul style="margin:0 0 24px;padding-left:20px;color:#374151;font-size:15px;line-height:2;">
      <li>Earn &amp; spend Swap Points on every trade</li>
      <li>Priority listing visibility in your node</li>
      <li>Set "Accept SP" or "Donate" payment preferences</li>
    </ul>
    <div style="text-align:center;">
      <a href="${subscribeLink}"
         style="display:inline-block;background:${urgency};color:#ffffff;padding:14px 28px;border-radius:8px;text-decoration:none;font-weight:600;font-size:15px;">
        Subscribe Now – Keep My Swap Points
      </a>
    </div>`;

  if (!SENDGRID_API_KEY) return { success: false, error: 'SendGrid API key not configured' };

  const html = buildEmailHtml(`Trial Expiring Soon – Kids Club+`, bodyHtml, unsubscribeToken, false);
  try {
    const response = await fetch('https://api.sendgrid.com/v3/mail/send', {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${SENDGRID_API_KEY}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({
        personalizations: [{ to: [{ email: to }] }],
        from: { email: SENDGRID_FROM_EMAIL },
        reply_to: { email: SENDGRID_REPLY_TO_EMAIL },
        subject: `${emoji} Your Kids Club+ trial ends in ${daysRemaining} day${daysRemaining !== 1 ? 's' : ''}`,
        content: [{ type: 'text/html', value: html }],
      }),
    });
    if (!response.ok) {
      const errText = await response.text();
      return { success: false, error: `SendGrid ${response.status}: ${errText}` };
    }
    return { success: true, messageId: response.headers.get('x-message-id') || undefined };
  } catch (err) {
    return { success: false, error: err instanceof Error ? err.message : 'Unknown error' };
  }
}

async function processSubscriptionCancelledEmail(
  to: string,
  unsubscribeToken: string,
  data?: Record<string, any>
): Promise<{ success: boolean; messageId?: string; error?: string }> {
  const gracePeriodEndsAt = data?.grace_period_ends_at || '90 days from now';
  const reactivateLink = data?.reactivate_link || 'https://p2pkidsmarketplace.com/subscription';

  const bodyHtml = `
    <h2 style="margin:0 0 16px;color:#111827;font-size:22px;">Subscription Cancelled</h2>
    <p style="margin:0 0 12px;color:#374151;font-size:15px;line-height:1.6;">
      Your Kids Club+ subscription has been cancelled.
    </p>
    <div style="background:#FEF3C7;border-left:4px solid #F59E0B;padding:16px;border-radius:4px;margin:0 0 24px;">
      <strong style="color:#92400E;">90-Day Grace Period:</strong>
      <span style="color:#78350F;"> Your Swap Points will be frozen (not deleted) until <strong>${gracePeriodEndsAt}</strong>. Reactivate before then to restore access.</span>
    </div>
    <p style="margin:0 0 24px;color:#374151;font-size:15px;line-height:1.6;">
      You can still browse and sell items as a free member. Subscribe again before <strong>${gracePeriodEndsAt}</strong> to keep all your Swap Points.
    </p>
    <div style="text-align:center;">
      <a href="${reactivateLink}"
         style="display:inline-block;background:#10B981;color:#ffffff;padding:14px 28px;border-radius:8px;text-decoration:none;font-weight:600;font-size:15px;">
        Reactivate Kids Club+
      </a>
    </div>`;

  if (!SENDGRID_API_KEY) return { success: false, error: 'SendGrid API key not configured' };

  const html = buildEmailHtml('Subscription Cancelled – Kids Club+', bodyHtml, unsubscribeToken, true);
  try {
    const response = await fetch('https://api.sendgrid.com/v3/mail/send', {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${SENDGRID_API_KEY}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({
        personalizations: [{ to: [{ email: to }] }],
        from: { email: SENDGRID_FROM_EMAIL },
        reply_to: { email: SENDGRID_REPLY_TO_EMAIL },
        subject: 'Your Kids Club+ Subscription Has Been Cancelled',
        content: [{ type: 'text/html', value: html }],
      }),
    });
    if (!response.ok) {
      const errText = await response.text();
      return { success: false, error: `SendGrid ${response.status}: ${errText}` };
    }
    return { success: true, messageId: response.headers.get('x-message-id') || undefined };
  } catch (err) {
    return { success: false, error: err instanceof Error ? err.message : 'Unknown error' };
