/**
 * File: p2p-kids-marketplace/src/services/emailNotifications.ts
 * MODULE-14 TASK NOTIF-V2-009: Email Notification Service
 *
 * Sends critical and non-critical transactional emails via the send-email edge function.
 * - Critical emails (payment failures, security alerts) always sent – bypass opt-out.
 * - Non-critical emails respect notification_preferences.email_enabled per category.
 */

import { supabase } from '../config/supabase';

export interface EmailResult {
  success: boolean;
  error?: string;
  unsubscribeToken?: string;
}

interface SendEmailParams {
  to: string;
  type: string;
  userId?: string;
  notificationCategory?: string;
  isCritical?: boolean;
  data: Record<string, any>;
}

/**
 * EmailNotificationService
 * MODULE-14 TASK NOTIF-V2-009
 */
export class EmailNotificationService {
  /**
   * Core send method – invokes the send-email edge function.
   * All email sending goes through this method for consistent error handling.
   */
  static async sendEmail(params: SendEmailParams): Promise<EmailResult> {
    try {
      const { data, error } = await supabase.functions.invoke('send-email', {
        body: {
          type: params.type,
          to: params.to,
          userId: params.userId,
          notificationCategory: params.notificationCategory,
          isCritical: params.isCritical ?? false,
          data: params.data,
        },
      });

      if (error) {
        console.error('[EmailNotificationService] Edge function error:', error.message);
        return { success: false, error: error.message };
      }

      return {
        success: data?.success ?? false,
        error: data?.error,
        unsubscribeToken: data?.unsubscribeToken,
      };
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : 'Unknown error';
      console.error('[EmailNotificationService] Unexpected error:', message);
      return { success: false, error: message };
    }
  }

  /**
   * Check if user has email_enabled for a specific notification category.
   * Returns false on any error (fail-closed for opt-out safety).
   */
  static async isEmailEnabledForCategory(
    userId: string,
    category: string
  ): Promise<boolean> {
    try {
      const { data, error } = await supabase
        .from('notification_preferences')
        .select('email_enabled')
        .eq('user_id', userId)
        .eq('category', category)
        .maybeSingle();

      if (error || !data) return false;
      return data.email_enabled === true;
    } catch {
      return false;
    }
  }

  // ─────────────────────────────────────────────────────────────────
  // CRITICAL events – always sent regardless of user preferences
  // ─────────────────────────────────────────────────────────────────

  /**
   * Payment failure email (CRITICAL)
   * Sent when Stripe invoice.payment_failed event fires.
   */
  static async sendPaymentFailureEmail(
    userId: string,
    email: string,
    subscriptionId?: string,
    amount?: number,
    reason?: string
  ): Promise<EmailResult> {
    return EmailNotificationService.sendEmail({
      to: email,
      type: 'payment_failed',
      userId,
      notificationCategory: 'subscription',
      isCritical: true,
      data: {
        subscription_id: subscriptionId || '',
        amount: amount ?? 0,
        reason: reason || 'Your card was declined',
        retry_link: 'https://p2pkidsmarketplace.com/subscription/payment',
      },
    });
  }

  /**
   * Subscription cancellation confirmation (CRITICAL)
   * Sent when user cancels or subscription lapses.
   */
  static async sendSubscriptionCancelledEmail(
    userId: string,
    email: string,
    gracePeriodEndsAt: string
  ): Promise<EmailResult> {
    return EmailNotificationService.sendEmail({
      to: email,
      type: 'subscription_cancelled',
      userId,
      notificationCategory: 'subscription',
      isCritical: true,
      data: {
        grace_period_ends_at: new Date(gracePeriodEndsAt).toLocaleDateString('en-US', {
          year: 'numeric',
          month: 'long',
          day: 'numeric',
        }),
        reactivate_link: 'https://p2pkidsmarketplace.com/subscription',
      },
    });
  }

  /**
   * Account security alert (CRITICAL)
   * Sent on password change, new device login, or account settings change.
   */
  static async sendAccountSecurityAlertEmail(
    userId: string,
    email: string,
    alertType: 'password_changed' | 'new_device_login' | 'account_settings_changed',
    details?: string
  ): Promise<EmailResult> {
    return EmailNotificationService.sendEmail({
      to: email,
