{"content": "/**
 * Supabase Edge Function: email-unsubscribe
 * NOTIF-V2-009: One-click email unsubscribe handler
 *
 * GET /functions/v1/email-unsubscribe?token=<unsubscribe_token>
 *
 * Looks up the unsubscribe token in email_logs, then updates
 * notification_preferences.email_enabled = false for that category.
 * Returns a browser-renderable HTML response.
 */

import { serve } from 'https://deno.land/std@0.182.0/http/server.ts';
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2.39.0';

const SUPABASE_URL = Deno.env.get('SUPABASE_URL')!;
const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;

serve(async (req: Request) => {
  const url = new URL(req.url);
  const token = url.searchParams.get('token');

  if (!token || token.length < 32) {
    return htmlResponse('Invalid unsubscribe link. The link may be malformed or expired.', 400, false);
  }

  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);

  // Look up token in email_logs
  const { data: logEntry, error: lookupError } = await supabase
    .from('email_logs')
    .select('user_id, notification_category, is_critical, email_type')
    .eq('unsubscribe_token', token)
    .single();

  if (lookupError || !logEntry) {
    console.error('[email-unsubscribe] Token not found:', token.substring(0, 8) + '...');
    return htmlResponse('Unsubscribe link is invalid or has already been used.', 404, false);
  }

  const { user_id, notification_category } = logEntry;

  if (!user_id || !notification_category) {
    console.warn('[email-unsubscribe] Missing user_id or category for token');
    return htmlResponse('Unable to process unsubscribe request. Please update your settings in the app.', 400, false);
  }

  // Update notification_preferences to disable email for that category
  const { error: updateError } = await supabase
    .from('notification_preferences')
    .update({ email_enabled: false })
    .eq('user_id', user_id)
    .eq('category', notification_category);

  if (updateError) {
    console.error('[email-unsubscribe] Failed to update preferences:', updateError);
    return htmlResponse('Failed to process your unsubscribe request. Please try again or update settings in the app.', 500, false);
  }

  // Invalidate the token by clearing it (prevents replay)
  await supabase
    .from('email_logs')
    .update({ unsubscribe_token: null })
    .eq('unsubscribe_token', token);

  console.log(`[email-unsubscribe] Unsubscribed user ${user_id} from category '${notification_category}'`);

  return htmlResponse(
    `You have been unsubscribed from <strong>${categoryLabel(notification_category)}</strong> email notifications.`,
    200,
    true
  );
});

function categoryLabel(category: string): string {
  const labels: Record<string, string> = {
    subscription: 'Subscription & Membership',
    sp_events: 'Swap Points Events',
    badges: 'Badges & Achievements',
    trades: 'Trades & Transactions',
    system: 'System Updates',
  };
  return labels[category] || category;
}

function htmlResponse(message: string, status: number, success: boolean): Response {
  const accentColor = success ? '#10B981' : '#EF4444';
  const icon = success ? '✓' : '⚠';
  const html = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${success ? 'Unsubscribed' : 'Error'} – P2P Kids Marketplace</title>
  <style>
    * { box-sizing: border-box; }
    body {
      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Arial, sans-serif;
      background: #F3F4F6;
      display: flex;
      align-items: center;
      justify-content: center;
      min-height: 100vh;
      margin: 0;
      padding: 16px;
    }
    .card {
      background: white;
      border-radius: 16px;
      padding: 48px 40px;
      max-width: 480px;
      width: 100%;
      text-align: center;
      box-shadow: 0 4px 24px rgba(0,0,0,0.08);
    }
    .icon-circle {
      width: 72px; height: 72px;
      background: ${accentColor}1A;
      border-radius: 50%;
      display: flex; align-items: center; justify-content: center;
      margin: 0 auto 24px;
      font-size: 36px;
      color: ${accentColor};
    }
    h1 { color: #111827; font-size: 24px; margin: 0 0 12px; font-weight: 700; }
    p  { color: #6B7280; font-size: 15px; line-height: 1.6; margin: 0 0 12px; }
    .note { font-size: 13px; color: #9CA3AF; margin-top: 24px; }
    a { color: #3B82F6; text-decoration: none; font-weight: 500; }
    a:hover { text-decoration: underline; }
  </style>
</head>
<body>
  <div class="card">
    <div class="icon-circle">${icon}</div>
    <h1>${success ? 'Unsubscribed' : 'Something went wrong'}</h1>
    <p>${message}</p>
    ${success ? `
      <p>You'll still receive <strong>critical emails</strong> (payment failures, security alerts) that are required for your account.</p>
      <p class="note">Want to re-enable email notifications? Open the app → <a href="p2pkidsmarketplace://profile/notifications">Notification Settings</a>.</p>
    ` : `
      <p class="note">Please manage your email preferences directly in the app under <a href="p2pkidsmarketplace://profile/notifications">Profile → Notification Settings</a>.</p>
    `}
  </div>
</body>
</html>`;

  return new Response(html, {
    status,
    headers: { 'Content-Type': 'text/html; charset=utf-8' },
  });
}
