  try {
    const response = await fetch('https://api.sendgrid.com/v3/mail/send', {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${SENDGRID_API_KEY}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({
        personalizations: [{ to: [{ email: to }] }],
        from: { email: SENDGRID_FROM_EMAIL },
        reply_to: { email: SENDGRID_REPLY_TO_EMAIL },
        subject: 'Your Kids Club+ Subscription Has Been Cancelled',
        content: [{ type: 'text/html', value: html }],
      }),
    });
    if (!response.ok) {
      const errText = await response.text();
      return { success: false, error: `SendGrid ${response.status}: ${errText}` };
    }
    return { success: true, messageId: response.headers.get('x-message-id') || undefined };
  } catch (err) {
    return { success: false, error: err instanceof Error ? err.message : 'Unknown error' };
  }
}

async function processAccountSecurityAlertEmail(
  to: string,
  unsubscribeToken: string,
  data?: Record<string, any>
): Promise<{ success: boolean; messageId?: string; error?: string }> {
  const alertType = data?.alert_type || 'account_settings_changed';
  const occurredAt = data?.occurred_at || new Date().toLocaleString('en-US');
  const settingsLink = data?.settings_link || 'https://p2pkidsmarketplace.com/profile/settings';

  const alertLabels: Record<string, string> = {
    password_changed: 'Your password was changed',
    new_device_login: 'New device sign-in detected',
    account_settings_changed: 'Your account settings were changed',
  };
  const alertLabel = alertLabels[alertType] || 'Account activity detected';

  const bodyHtml = `
    <h2 style="margin:0 0 16px;color:#111827;font-size:22px;">🔐 Security Alert</h2>
    <p style="margin:0 0 12px;color:#374151;font-size:15px;line-height:1.6;">
      We detected the following activity on your P2P Kids Marketplace account:
    </p>
    <div style="background:#EFF6FF;border-left:4px solid #3B82F6;padding:16px;border-radius:4px;margin:0 0 16px;">
      <strong style="color:#1E40AF;">${alertLabel}</strong><br>
      <span style="color:#3B82F6;font-size:13px;">${occurredAt}</span>
      ${data?.details ? `<br><span style="color:#374151;font-size:13px;margin-top:4px;display:block;">${data.details}</span>` : ''}
    </div>
    <p style="margin:0 0 24px;color:#374151;font-size:15px;line-height:1.6;">
      If this was you, no action is needed. If you did not make this change, please secure your account immediately.
    </p>
    <div style="text-align:center;">
      <a href="${settingsLink}"
         style="display:inline-block;background:#3B82F6;color:#ffffff;padding:14px 28px;border-radius:8px;text-decoration:none;font-weight:600;font-size:15px;">
        Review Account Settings
      </a>
    </div>`;

  if (!SENDGRID_API_KEY) return { success: false, error: 'SendGrid API key not configured' };

  const html = buildEmailHtml('Security Alert – Kids Marketplace', bodyHtml, unsubscribeToken, true);
  try {
    const response = await fetch('https://api.sendgrid.com/v3/mail/send', {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${SENDGRID_API_KEY}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({
        personalizations: [{ to: [{ email: to }] }],
        from: { email: SENDGRID_FROM_EMAIL },
        reply_to: { email: SENDGRID_REPLY_TO_EMAIL },
        subject: `Security Alert: ${alertLabel}`,
        content: [{ type: 'text/html', value: html }],
      }),
    });
    if (!response.ok) {
      const errText = await response.text();
      return { success: false, error: `SendGrid ${response.status}: ${errText}` };
    }
    return { success: true, messageId: response.headers.get('x-message-id') || undefined };
  } catch (err) {
    return { success: false, error: err instanceof Error ? err.message : 'Unknown error' };
  }
}

// =============================================================================
// Main serve handler
// =============================================================================
serve(async (req: Request) => {
  // Handle CORS
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: { 'Access-Control-Allow-Origin': '*' } });
  }

  if (req.method !== 'POST') {
    return new Response(JSON.stringify({ error: 'Method not allowed' }), {
      status: 405,
      headers: { 'Content-Type': 'application/json' },
    });
  }

  try {
    const body = await req.json();
    const request = body as SendEmailRequest;

    // Validate request
    const validation = validateRequest(request);
    if (!validation.valid) {
      return new Response(
        JSON.stringify({ error: validation.error }),
        { status: 400, headers: { 'Content-Type': 'application/json' } }
      );
    }

    // NOTIF-V2-009: Generate unsubscribe token for all emails
    const unsubscribeToken = generateUnsubscribeToken();
    const isCritical = request.isCritical ?? false;

    // Process email based on type
    let result: { success: boolean; messageId?: string; error?: string };

    switch (request.type) {
      case 'welcome':
        result = await processWelcomeEmail(request.to, request.data);
        break;
      case 'password_reset':
        result = await processPasswordResetEmail(request.to, request.data);
        break;
      case 'trade_notification':
        result = await processTradeNotificationEmail(request.to, request.data);
        break;
      case 'transaction_confirmation':
        result = await processTransactionConfirmationEmail(request.to, request.data);
        break;
      case 'subscription_status':
        result = await processSubscriptionStatusEmail(request.to, request.data);
        break;
      case 'id_badge_approved':
      case 'id_badge_rejected':
      case 'id_badge_submission':
        result = await processIDBadgeEmail(request.to, request.type, request.data);
        break;
      // NOTIF-V2-009: New critical/event email types
      case 'payment_failed':
        result = await processPaymentFailedEmail(request.to, unsubscribeToken, request.data);
        break;
      case 'trial_expiring':
        result = await processTrialExpiringEmail(request.to, unsubscribeToken, request.data);
        break;
      case 'subscription_cancelled':
        result = await processSubscriptionCancelledEmail(request.to, unsubscribeToken, request.data);
        break;
      case 'account_security_alert':
        result = await processAccountSecurityAlertEmail(request.to, unsubscribeToken, request.data);
        break;
      default:
        return new Response(
          JSON.stringify({ error: 'Unknown email type' }),
          { status: 400, headers: { 'Content-Type': 'application/json' } }
        );
    }

    // NOTIF-V2-009: Log email delivery (non-blocking – fire and forget)
    logEmailDelivery({
      userId: request.userId,
      recipientEmail: request.to,
      emailType: request.type,
      notificationCategory: request.notificationCategory,
      isCritical,
      status: result.success ? 'sent' : 'failed',
      sendgridMessageId: result.messageId,
      errorMessage: result.error,
      unsubscribeToken,
    });

    const statusCode = result.success ? 200 : 500;
    return new Response(
      JSON.stringify({ ...result, unsubscribeToken: result.success ? unsubscribeToken : undefined }),
      { status: statusCode, headers: { 'Content-Type': 'application/json' } }
    );
  } catch (error) {
    console.error('Email function error:', error);
    return new Response(
      JSON.stringify({
        success: false,
        error: error instanceof Error ? error.message : 'Unknown error',
      }),
      { status: 500, headers: { 'Content-Type': 'application/json' } }
    );
  }
});"}

{"content": "/**
 * File: p2p-kids-marketplace/src/services/emailNotifications.ts
 * MODULE-14 TASK NOTIF-V2-009: Email Notification Service
 *
 * Sends critical and non-critical transactional emails via the send-email edge function.
 * - Critical emails (payment failures, security alerts) always sent – bypass opt-out.
 * - Non-critical emails respect notification_preferences.email_enabled per category.
 */

import { supabase } from '../config/supabase';

export interface EmailResult {
  success: boolean;
  error?: string;
  unsubscribeToken?: string;
}

interface SendEmailParams {
  to: string;
  type: string;
  userId?: string;
  notificationCategory?: string;
  isCritical?: boolean;
  data: Record<string, any>;
}

/**
 * EmailNotificationService
 * MODULE-14 TASK NOTIF-V2-009
 */
export class EmailNotificationService {
  /**
   * Core send method – invokes the send-email edge function.
   * All email sending goes through this method for consistent error handling.
   */
  static async sendEmail(params: SendEmailParams): Promise<EmailResult> {
    try {
      const { data, error } = await supabase.functions.invoke('send-email', {
        body: {
          type: params.type,
          to: params.to,
          userId: params.userId,
          notificationCategory: params.notificationCategory,
          isCritical: params.isCritical ?? false,
          data: params.data,
        },
      });

      if (error) {
        console.error('[EmailNotificationService] Edge function error:', error.message);
        return { success: false, error: error.message };
      }

      return {
        success: data?.success ?? false,
        error: data?.error,
        unsubscribeToken: data?.unsubscribeToken,
      };
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : 'Unknown error';
      console.error('[EmailNotificationService] Unexpected error:', message);
      return { success: false, error: message };
    }
  }

  /**
   * Check if user has email_enabled for a specific notification category.
   * Returns false on any error (fail-closed for opt-out safety).
   */
  static async isEmailEnabledForCategory(
    userId: string,
    category: string
  ): Promise<boolean> {
    try {
      const { data, error } = await supabase
        .from('notification_preferences')
        .select('email_enabled')
        .eq('user_id', userId)
        .eq('category', category)
        .maybeSingle();

      if (error || !data) return false;
      return data.email_enabled === true;
    } catch {
      return false;
    }
  }

  // ─────────────────────────────────────────────────────────────────
  // CRITICAL events – always sent regardless of user preferences
  // ─────────────────────────────────────────────────────────────────

  /**
   * Payment failure email (CRITICAL)
   * Sent when Stripe invoice.payment_failed event fires.
   */
  static async sendPaymentFailureEmail(
    userId: string,
    email: string,
    subscriptionId?: string,
    amount?: number,
    reason?: string
  ): Promise<EmailResult> {
    return EmailNotificationService.sendEmail({
      to: email,
      type: 'payment_failed',
      userId,
      notificationCategory: 'subscription',
      isCritical: true,
      data: {
        subscription_id: subscriptionId || '',
        amount: amount ?? 0,
        reason: reason || 'Your card was declined',
        retry_link: 'https://p2pkidsmarketplace.com/subscription/payment',
      },
    });
  }

  /**
   * Subscription cancellation confirmation (CRITICAL)
   * Sent when user cancels or subscription lapses.
   */
  static async sendSubscriptionCancelledEmail(
    userId: string,
    email: string,
    gracePeriodEndsAt: string
  ): Promise<EmailResult> {
    return EmailNotificationService.sendEmail({
      to: email,
      type: 'subscription_cancelled',
      userId,
      notificationCategory: 'subscription',
      isCritical: true,
      data: {
        grace_period_ends_at: new Date(gracePeriodEndsAt).toLocaleDateString('en-US', {
          year: 'numeric',
          month: 'long',
          day: 'numeric',
        }),
        reactivate_link: 'https://p2pkidsmarketplace.com/subscription',
      },
    });
  }

  /**
   * Account security alert (CRITICAL)
   * Sent on password change, new device login, or account settings change.
   */
  static async sendAccountSecurityAlertEmail(
    userId: string,
    email: string,
    alertType: 'password_changed' | 'new_device_login' | 'account_settings_changed',
    details?: string
  ): Promise<EmailResult> {
    return EmailNotificationService.sendEmail({
      to: email,
      type: 'account_security_alert',
      userId,
      notificationCategory: 'system',
      isCritical: true,
      data: {
        alert_type: alertType,
        details: details || '',
        settings_link: 'https://p2pkidsmarketplace.com/profile/settings',
        occurred_at: new Date().toLocaleString('en-US', {
          dateStyle: 'medium',
          timeStyle: 'short',
        }),
      },
    });
  }

  // ─────────────────────────────────────────────────────────────────
  // NON-CRITICAL events – respect email_enabled preference
  // ─────────────────────────────────────────────────────────────────

  /**
   * Trial expiring reminder (non-critical)
   * Skipped if user has email_enabled=false for 'subscription' category.
   */
  static async sendTrialExpiringEmail(
    userId: string,
    email: string,
    daysRemaining: number,
    trialEndsAt: string
  ): Promise<EmailResult> {
    const isEnabled = await EmailNotificationService.isEmailEnabledForCategory(
      userId,
      'subscription'
    );

    if (!isEnabled) {
      console.log('[EmailNotificationService] Trial expiry email skipped – user opted out', userId);
      return { success: true };
    }

    return EmailNotificationService.sendEmail({
      to: email,
      type: 'trial_expiring',
      userId,
      notificationCategory: 'subscription',
      isCritical: false,
      data: {
        days_remaining: daysRemaining,
        trial_ends_at: new Date(trialEndsAt).toLocaleDateString('en-US', {
          year: 'numeric',
          month: 'long',
          day: 'numeric',
        }),
        subscribe_link: 'https://p2pkidsmarketplace.com/subscription',
      },
    });
  }

  /**
   * Subscription renewed confirmation (non-critical)
   * Skipped if user has email_enabled=false for 'subscription' category.
   */
  static async sendSubscriptionRenewedEmail(
    userId: string,
    email: string,
    nextBillingDate: string
  ): Promise<EmailResult> {
    const isEnabled = await EmailNotificationService.isEmailEnabledForCategory(
      userId,
      'subscription'
    );

    if (!isEnabled) {
      return { success: true };
    }

    return EmailNotificationService.sendEmail({
      to: email,
      type: 'subscription_status',
      userId,
      notificationCategory: 'subscription',
      isCritical: false,
      data: {
        status: 'renewed',
        tier: 'Kids Club+',
        expiryDate: new Date(nextBillingDate).toLocaleDateString('en-US', {
          year: 'numeric',
          month: 'long',
          day: 'numeric',
        }),
      },
    });
  }
}
