 * Unit Tests: emailNotifications.ts
 * MODULE-14 TASK NOTIF-V2-009
 * Location: p2p-kids-marketplace/src/__tests__/services/emailNotifications.test.ts
 */

import { EmailNotificationService } from '../../services/emailNotifications';

// ─── Supabase mock ───────────────────────────────────────────────────────────
const mockInvoke = jest.fn();
const mockFrom = jest.fn();
const mockSelect = jest.fn();
const mockEq = jest.fn();
const mockMaybeSingle = jest.fn();

jest.mock('../../config/supabase', () => ({
  supabase: {
    functions: { invoke: (...args: any[]) => mockInvoke(...args) },
    from: (...args: any[]) => mockFrom(...args),
  },
}));

// Chain builder helper
function buildChain(finalValue: any) {
  return {
    select: jest.fn().mockReturnThis(),
    eq: jest.fn().mockReturnThis(),
    maybeSingle: jest.fn().mockResolvedValue(finalValue),
    single: jest.fn().mockResolvedValue(finalValue),
  };
}

// ─── Test helpers ────────────────────────────────────────────────────────────
const TEST_USER_ID = 'user-123';
const TEST_EMAIL = 'parent@example.com';

function mockSuccessInvoke() {
  mockInvoke.mockResolvedValue({ data: { success: true, unsubscribeToken: 'abc123' }, error: null });
}

function mockFailedInvoke(msg: string) {
  mockInvoke.mockResolvedValue({ data: { success: false, error: msg }, error: null });
}

function mockEmailEnabled(enabled: boolean) {
  mockFrom.mockReturnValue(buildChain({ data: { email_enabled: enabled }, error: null }));
}

beforeEach(() => {
  jest.clearAllMocks();
});

// ─────────────────────────────────────────────────────────────────────────────
// EmailNotificationService.sendEmail (core)
// ─────────────────────────────────────────────────────────────────────────────
describe('EmailNotificationService.sendEmail', () => {
  it('invokes send-email edge function with correct payload', async () => {
    mockSuccessInvoke();

    const result = await EmailNotificationService.sendEmail({
      to: TEST_EMAIL,
      type: 'payment_failed',
      userId: TEST_USER_ID,
      notificationCategory: 'subscription',
      isCritical: true,
      data: { amount: 9.99 },
    });

    expect(mockInvoke).toHaveBeenCalledWith('send-email', {
      body: expect.objectContaining({
        type: 'payment_failed',
        to: TEST_EMAIL,
        userId: TEST_USER_ID,
        isCritical: true,
      }),
    });
    expect(result.success).toBe(true);
    expect(result.unsubscribeToken).toBe('abc123');
  });

  it('returns failure when edge function returns error object', async () => {
    mockInvoke.mockResolvedValue({ data: null, error: { message: 'Function timeout' } });

    const result = await EmailNotificationService.sendEmail({
      to: TEST_EMAIL,
      type: 'payment_failed',
      userId: TEST_USER_ID,
      data: {},
    });

    expect(result.success).toBe(false);
    expect(result.error).toBe('Function timeout');
  });

  it('returns failure when edge function returns success=false', async () => {
    mockFailedInvoke('SendGrid API key not configured');

    const result = await EmailNotificationService.sendEmail({
      to: TEST_EMAIL,
      type: 'trial_expiring',
      userId: TEST_USER_ID,
      data: {},
    });

    expect(result.success).toBe(false);
    expect(result.error).toBe('SendGrid API key not configured');
  });

  it('handles unexpected throw from invoke gracefully', async () => {
    mockInvoke.mockRejectedValue(new Error('Network error'));

    const result = await EmailNotificationService.sendEmail({
      to: TEST_EMAIL,
      type: 'payment_failed',
      userId: TEST_USER_ID,
      data: {},
    });

    expect(result.success).toBe(false);
    expect(result.error).toBe('Network error');
  });
});

// ─────────────────────────────────────────────────────────────────────────────
// isEmailEnabledForCategory
// ─────────────────────────────────────────────────────────────────────────────
describe('EmailNotificationService.isEmailEnabledForCategory', () => {
  it('returns true when email_enabled is true', async () => {
    mockFrom.mockReturnValue(buildChain({ data: { email_enabled: true }, error: null }));

    const result = await EmailNotificationService.isEmailEnabledForCategory(
      TEST_USER_ID, 'subscription'
    );
    expect(result).toBe(true);
  });

  it('returns false when email_enabled is false', async () => {
    mockFrom.mockReturnValue(buildChain({ data: { email_enabled: false }, error: null }));

    const result = await EmailNotificationService.isEmailEnabledForCategory(
      TEST_USER_ID, 'subscription'
    );
    expect(result).toBe(false);
  });

  it('returns false when preference row is missing', async () => {
    mockFrom.mockReturnValue(buildChain({ data: null, error: null }));

    const result = await EmailNotificationService.isEmailEnabledForCategory(
      TEST_USER_ID, 'subscription'
    );
    expect(result).toBe(false);
  });

  it('returns false when DB query errors', async () => {
    mockFrom.mockReturnValue(buildChain({ data: null, error: { message: 'DB error' } }));

    const result = await EmailNotificationService.isEmailEnabledForCategory(
      TEST_USER_ID, 'subscription'
    );
    expect(result).toBe(false);
  });
});

// ─────────────────────────────────────────────────────────────────────────────
// sendPaymentFailureEmail (CRITICAL)
// ─────────────────────────────────────────────────────────────────────────────
describe('EmailNotificationService.sendPaymentFailureEmail', () => {
  it('sends email without checking preferences (critical)', async () => {
    mockSuccessInvoke();

