{"content": "/**
 * Integration Tests: NOTIF-V2-009 Email Notifications
 * MODULE-14 TASK NOTIF-V2-009
 *
 * Tests EmailNotificationService against staging Supabase.
 * Run with: RUN_SUPABASE_E2E=true npm run test:e2e
 *
 * Required: EXPO_PUBLIC_SUPABASE_URL and EXPO_PUBLIC_SUPABASE_ANON_KEY env vars.
 */

import { createClient } from '@supabase/supabase-js';
import { EmailNotificationService } from '../../src/services/emailNotifications';

const RUN_E2E = process.env.RUN_SUPABASE_E2E === 'true';

// Mock supabase for non-E2E runs
jest.mock('../../src/config/supabase', () => {
  if (process.env.RUN_SUPABASE_E2E !== 'true') {
    return {
      supabase: {
        functions: { invoke: jest.fn().mockResolvedValue({ data: { success: true }, error: null }) },
        from: jest.fn().mockReturnValue({
          select: jest.fn().mockReturnThis(),
          eq: jest.fn().mockReturnThis(),
          maybeSingle: jest.fn().mockResolvedValue({ data: { email_enabled: true }, error: null }),
        }),
      },
    };
  }
  return jest.requireActual('../../src/config/supabase');
});

describe('NOTIF-V2-009: Email Notification Integration', () => {
  const STAGING_USER_ID = process.env.E2E_TEST_USER_ID || 'test-user-uuid';
  const STAGING_EMAIL = process.env.E2E_TEST_EMAIL || 'test@example.com';

  describe('EmailNotificationService', () => {
    it('TC-009-01: sendPaymentFailureEmail – sends successfully (critical bypasses prefs)', async () => {
      const result = await EmailNotificationService.sendPaymentFailureEmail(
        STAGING_USER_ID,
        STAGING_EMAIL,
        'sub_test_123',
        9.99,
        'Card was declined'
      );

      expect(result.success).toBe(true);
      if (RUN_E2E) {
        expect(result.unsubscribeToken).toBeDefined();
      }
    });

    it('TC-009-02: sendTrialExpiringEmail – sends when email_enabled=true', async () => {
      if (!RUN_E2E) {
        // Unit-mode: mock returns email_enabled=true
        const result = await EmailNotificationService.sendTrialExpiringEmail(
          STAGING_USER_ID,
          STAGING_EMAIL,
          7,
          '2026-05-23T00:00:00Z'
        );
        expect(result.success).toBe(true);
        return;
      }

      // E2E: Ensure subscription email is enabled for test user, then send
      const supabaseAdmin = createClient(
        process.env.EXPO_PUBLIC_SUPABASE_URL!,
        process.env.SUPABASE_SERVICE_ROLE_KEY!
      );
      await supabaseAdmin
        .from('notification_preferences')
        .update({ email_enabled: true })
        .eq('user_id', STAGING_USER_ID)
        .eq('category', 'subscription');

      const result = await EmailNotificationService.sendTrialExpiringEmail(
        STAGING_USER_ID,
        STAGING_EMAIL,
        7,
        '2026-05-23T00:00:00Z'
      );
      expect(result.success).toBe(true);
    });

    it('TC-009-03: sendTrialExpiringEmail – skipped when email_enabled=false', async () => {
      if (!RUN_E2E) {
        // Already tested in unit tests
        return;
      }

      const supabaseAdmin = createClient(
        process.env.EXPO_PUBLIC_SUPABASE_URL!,
        process.env.SUPABASE_SERVICE_ROLE_KEY!
      );
      await supabaseAdmin
        .from('notification_preferences')
        .update({ email_enabled: false })
        .eq('user_id', STAGING_USER_ID)
        .eq('category', 'subscription');

      const result = await EmailNotificationService.sendTrialExpiringEmail(
        STAGING_USER_ID,
        STAGING_EMAIL,
        3,
        '2026-04-20T00:00:00Z'
      );
      // Should silently succeed (skipped)
      expect(result.success).toBe(true);
    });

    it('TC-009-04: sendSubscriptionCancelledEmail – sends (critical)', async () => {
      const result = await EmailNotificationService.sendSubscriptionCancelledEmail(
        STAGING_USER_ID,
        STAGING_EMAIL,
        '2026-07-16T00:00:00Z'
      );
      expect(result.success).toBe(true);
    });

    it('TC-009-05: sendAccountSecurityAlertEmail – sends for password_changed', async () => {
      const result = await EmailNotificationService.sendAccountSecurityAlertEmail(
        STAGING_USER_ID,
        STAGING_EMAIL,
        'password_changed',
        'Changed via iOS app'
      );
      expect(result.success).toBe(true);
    });

    it('TC-009-06: isEmailEnabledForCategory – returns correct value from DB', async () => {
      if (!RUN_E2E) {
        const result = await EmailNotificationService.isEmailEnabledForCategory(
          STAGING_USER_ID, 'subscription'
        );
        expect(typeof result).toBe('boolean');
        return;
      }

      const supabaseAdmin = createClient(
        process.env.EXPO_PUBLIC_SUPABASE_URL!,
        process.env.SUPABASE_SERVICE_ROLE_KEY!
      );
      await supabaseAdmin
        .from('notification_preferences')
        .update({ email_enabled: true })
        .eq('user_id', STAGING_USER_ID)
        .eq('category', 'subscription');

      const result = await EmailNotificationService.isEmailEnabledForCategory(
        STAGING_USER_ID, 'subscription'
      );
      expect(result).toBe(true);
    });

    it('TC-009-07: email_logs row created after successful send (E2E only)', async () => {
      if (!RUN_E2E) {
        return; // Covered by edge function logs in E2E
      }

      const supabaseAdmin = createClient(
        process.env.EXPO_PUBLIC_SUPABASE_URL!,
        process.env.SUPABASE_SERVICE_ROLE_KEY!
      );

      const before = Date.now();

      await EmailNotificationService.sendPaymentFailureEmail(
        STAGING_USER_ID,
        STAGING_EMAIL,
        'sub_e2e_test',
        9.99,
        'E2E test'
      );

      // Allow 2s for async log write
      await new Promise((r) => setTimeout(r, 2000));

      const { data: logs } = await supabaseAdmin
        .from('email_logs')
        .select('id, email_type, status, is_critical, unsubscribe_token')
        .eq('email_type', 'payment_failed')
        .gte('created_at', new Date(before).toISOString())
        .order('created_at', { ascending: false })
        .limit(1);

      expect(logs?.length).toBeGreaterThan(0);
      const log = logs![0];
      expect(log.email_type).toBe('payment_failed');
      expect(log.is_critical).toBe(true);
      expect(log.unsubscribe_token).toBeDefined();
      expect(['sent', 'failed']).toContain(log.status);
    });
  });
});
