 */
async function updateEmailLogStatus(
  logId: string,
  sendgridMessageId: string | undefined,
  status: 'sent' | 'failed',
  errorMessage?: string
): Promise<void> {
  try {
    await supabase.rpc('update_email_log_status', {
      p_log_id: logId,
      p_sendgrid_message_id: sendgridMessageId || null,
      p_status: status,
      p_error_message: errorMessage || null,
